const utilizador = { nome: "Rui", cargo: "Developer" };
const utilizadorCongelado = Object.freeze(utilizador);

utilizadorCongelado.cargo = "Manager"; // ignorado (modo não-estrito)
console.log(utilizadorCongelado.cargo); // "Developer"

const rascunho = Object.seal({ titulo: "Rascunho", versao: 1 });
rascunho.versao = 2;      // permitido, a propriedade continua writable
delete rascunho.titulo;   // ignorado, objeto selado não permite remover
rascunho.autor = "Rui";   // ignorado, objeto selado não é extensível
console.log(rascunho); // { titulo: 'Rascunho', versao: 2 }

const definicoesPadrao = { tema: "claro", tamanhoFonte: 14, notificacoes: true };
const preferenciasUtilizador = { tema: "escuro" };

const definicoesFinais = Object.assign({}, definicoesPadrao, preferenciasUtilizador);
console.log(definicoesFinais); // { tema: 'escuro', tamanhoFonte: 14, notificacoes: true }
console.log(definicoesPadrao.tema); // "claro", o original não foi tocado

const alvo = { a: 1 };
const resultado = Object.assign(alvo, { b: 2 }, { a: 3 });
console.log(resultado === alvo); // true, o alvo foi mutado e devolvido
console.log(alvo); // { a: 3, b: 2 }

// cópia rasa: o objeto aninhado continua partilhado por referência
const original = { endereco: { cidade: "Porto" } };
const copia = Object.assign({}, original);
copia.endereco.cidade = "Lisboa";
console.log(original.endereco.cidade); // "Lisboa"

const produto = {};

Object.defineProperty(produto, "id", {
  value: "PRD-001",
  writable: false,
  enumerable: true,
  configurable: false,
});

Object.defineProperty(produto, "_stockInterno", {
  value: 50,
  writable: true,
  enumerable: false,
  configurable: false,
});

Object.defineProperty(produto, "stock", {
  enumerable: true,
  get() {
    return produto._stockInterno;
  },
  set(quantidade) {
    if (quantidade < 0) {
      throw new RangeError("O stock não pode ser negativo.");
    }
    produto._stockInterno = quantidade;
  },
});

produto.id = "OUTRO"; // ignorado, writable: false
produto.stock = 45;

console.log(Object.keys(produto)); // ["id", "stock"], _stockInterno fica escondido
console.log(Object.getOwnPropertyDescriptor(produto, "id"));
// { value: 'PRD-001', writable: false, enumerable: true, configurable: false }

const dicionario = Object.create(null); // sem protótipo, sem hasOwnProperty herdado
dicionario.palavra = "algoritmo";

console.log(Object.hasOwn(dicionario, "palavra")); // true
console.log(Object.hasOwn(dicionario, "toString")); // false
// dicionario.hasOwnProperty("palavra"); // TypeError: dicionario.hasOwnProperty is not a function

const config = {
  hasOwnProperty() {
    return "intercetado!";
  },
  ativo: true,
};

console.log(config.hasOwnProperty("ativo")); // "intercetado!", método foi sobreposto
console.log(Object.hasOwn(config, "ativo"));  // true, imune à sobreposição

