function criarConfiguracaoFixa(base, substituicoes) {
  const configuracao = Object.assign({}, base, substituicoes);
  return Object.freeze(configuracao);
}

const padrao = { tema: "claro", idioma: "pt-PT", notificacoes: true };
const config = criarConfiguracaoFixa(padrao, { tema: "escuro" });

console.log(config); // { tema: 'escuro', idioma: 'pt-PT', notificacoes: true }
console.log(Object.isFrozen(config)); // true
console.log(Object.isFrozen(padrao)); // false, o original nunca foi tocado

config.tema = "azul"; // ignorado silenciosamente (ou lança TypeError em modo estrito)
console.log(config.tema); // "escuro"

const base = { nome: "Ana", idade: 30 };

const objetoSelado = Object.seal({ ...base });
const objetoCongelado = Object.freeze({ ...base });

objetoSelado.pais = "Portugal";
objetoCongelado.pais = "Portugal";

objetoSelado.idade = 31;
objetoCongelado.idade = 31;

delete objetoSelado.nome;
delete objetoCongelado.nome;

console.log(objetoSelado); // { nome: 'Ana', idade: 31 }
console.log(objetoCongelado); // { nome: 'Ana', idade: 30 }

console.log(Object.isSealed(objetoSelado)); // true
console.log(Object.isFrozen(objetoSelado)); // false, idade continua writable

console.log(Object.isSealed(objetoCongelado)); // true, todo o objeto congelado está também selado
console.log(Object.isFrozen(objetoCongelado)); // true

function criarContaBancaria(saldoInicial) {
  const conta = {};

  Object.defineProperty(conta, "_saldo", {
    value: saldoInicial,
    writable: true,
    enumerable: false,
    configurable: false,
  });

  Object.defineProperty(conta, "saldo", {
    enumerable: true,
    configurable: false,
    get() {
      return conta._saldo;
    },
    set(novoValor) {
      if (typeof novoValor !== "number" || Number.isNaN(novoValor)) {
        throw new TypeError("O saldo tem de ser um número.");
      }
      if (novoValor < 0) {
        throw new RangeError("O saldo não pode ser negativo.");
      }
      conta._saldo = novoValor;
    },
  });

  return conta;
}

const conta = criarContaBancaria(100);
console.log(conta.saldo); // 100
conta.saldo = 250;
console.log(conta.saldo); // 250

console.log(Object.keys(conta)); // ["saldo"], _saldo fica escondido
console.log(Object.hasOwn(conta, "_saldo")); // true

try {
  conta.saldo = -50;
} catch (erro) {
  console.log(erro.message); // "O saldo não pode ser negativo."
}

function saoIguaisRaso(a, b) {
  if (a === b) {
    return true;
  }

  const chavesA = Object.keys(a);
  const chavesB = Object.keys(b);

  if (chavesA.length !== chavesB.length) {
    return false;
  }

  return chavesA.every((chave) => {
    return Object.hasOwn(b, chave) && Object.is(a[chave], b[chave]);
  });
}

const semPrototipo = Object.create(null);
semPrototipo.x = NaN;
semPrototipo.y = 0;

const outro = { x: NaN, y: -0 };

console.log(saoIguaisRaso(semPrototipo, outro)); // false, Object.is(0, -0) é false
console.log(saoIguaisRaso({ x: NaN }, { x: NaN })); // true, Object.is(NaN, NaN) é true
console.log(saoIguaisRaso({ a: 1, b: 2 }, { a: 1 })); // false, número de chaves diferente
